using ERPWMS.Database.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System;using System.Linq;using System.Security.Claims;using System.Threading.Tasks;
using ERPWMS.Database;
namespace ERPWMS.Controllers.Workflow{[Authorize]public class WorkflowInstanceController:Controller{private readonly AppDbContext _context;public WorkflowInstanceController(AppDbContext c){_context=c;}
private int Uid(){var cl=User.FindFirstValue(ClaimTypes.NameIdentifier);if(int.TryParse(cl,out var i)&&i>0)return i;var u=_context.Users.FirstOrDefault();return u!=null?u.Id:1;}
[HttpGet]public IActionResult Index()=>View();
[HttpGet]public async Task<IActionResult> GetStatistics(){var l=await _context.WorkflowInstances.ToListAsync();return Json(new{total=l.Count,active=l.Count(i=>i.Status=="InProgress"),inactive=l.Count(i=>i.Status=="Rejected"||i.Status=="Cancelled"),addedThisMonth=l.Count(i=>i.CreatedDate.HasValue&&i.CreatedDate.Value.Month==DateTime.Now.Month&&i.CreatedDate.Value.Year==DateTime.Now.Year)});}
[HttpGet]public async Task<IActionResult> GetAll(){var l=await _context.WorkflowInstances.Include(i=>i.WorkflowDef).Include(i=>i.CurrentStage).OrderBy(i => i.WorkflowInstId).Select(i=>new{workflowInstId=i.WorkflowInstId,workflowName=i.WorkflowDef!=null?i.WorkflowDef.WorkflowName:"-",recordType=i.RecordType??"",recordId=i.RecordId,currentStage=i.CurrentStage!=null?i.CurrentStage.StageName:"-",status=i.Status??"InProgress",startedDate=i.StartedDate,createdDate=i.CreatedDate}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetWorkflows(){var l=await _context.WorkflowDefinitions.Where(d=>d.IsActive == true&&d.IsDeleted!=true).Select(d=>new{workflowDefId=d.WorkflowDefId,workflowName=d.WorkflowName}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetFirstStages(int workflowDefId){var l=await _context.WorkflowStages.Where(s=>s.WorkflowDefId==workflowDefId&&s.IsDeleted!=true).OrderBy(s=>s.StageOrder).Select(s=>new{stageId=s.StageId,stageName=s.StageName}).ToListAsync();return Json(l);}
[HttpGet]public IActionResult AddPartial()=>PartialView("_AddForm");
[HttpGet]public async Task<IActionResult> EditPartial(int id){var i=await _context.WorkflowInstances.FindAsync(id);if(i==null)return NotFound();return PartialView("_EditForm",i);}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Register(int workflowDefId,int recordId,string recordType,int currentStageId){try{if(workflowDefId<=0||recordId<=0||currentStageId<=0)return Json(new{success=false,message="All fields required."});if(string.IsNullOrWhiteSpace(recordType))return Json(new{success=false,message="Record type required."});_context.WorkflowInstances.Add(new WorkflowInstance{WorkflowDefId=workflowDefId,RecordId=recordId,RecordType=recordType.Trim(),CurrentStageId=currentStageId,Status="InProgress",StartedDate=DateTime.Now,CreatedBy=Uid().ToString(),CreatedDate=DateTime.Now});await _context.SaveChangesAsync();return Json(new{success=true,message="Workflow started!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(int workflowInstId,int recordId,string recordType,string status){try{var i=await _context.WorkflowInstances.FindAsync(workflowInstId);if(i==null)return Json(new{success=false});i.RecordId=recordId;i.RecordType=recordType;i.Status=status;if(status=="Completed"||status=="Rejected"||status=="Cancelled")i.CompletedDate=DateTime.Now;i.UpdatedBy=Uid().ToString();i.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Instance updated!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){try{var i=await _context.WorkflowInstances.FindAsync(id);if(i==null)return Json(new{success=false});_context.WorkflowInstances.Remove(i);await _context.SaveChangesAsync();return Json(new{success=true,message="Deleted."});}catch(Exception ex){return Json(new{success=false,message=ex.Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Toggle(int id){try{var i=await _context.WorkflowInstances.FindAsync(id);if(i==null)return Json(new{success=false});i.Status=i.Status=="InProgress"?"Completed":"InProgress";i.UpdatedBy=Uid().ToString();i.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Status: "+i.Status});}catch(Exception ex){return Json(new{success=false,message=ex.Message});}}
[HttpGet]public async Task<IActionResult> Profile(int id){var i=await _context.WorkflowInstances.Include(x=>x.WorkflowDef).Include(x=>x.CurrentStage).FirstOrDefaultAsync(x=>x.WorkflowInstId==id);if(i==null)return NotFound();ViewBag.Logs=await _context.WorkflowInstanceLogs.Include(l=>l.Action).Include(l=>l.StageFrom).Include(l=>l.StageTo).Include(l=>l.User).Where(l=>l.WorkflowInstId==id).OrderByDescending(l=>l.ActionDate).ToListAsync();return View(i);}
}}
